// "We picked AP", so every call goes to the nearest region
public sealed class Seats(ISeatStore nearest)
{
    // During a partition, two regions can each sell the same seat
    public Task<bool> BookAsync(Guid flight, string seat, CancellationToken ct) =>
        nearest.TryAssignAsync(flight, seat, ct);

    public Task<string[]> FreeSeatsAsync(Guid flight, CancellationToken ct) =>
        nearest.GetFreeSeatsAsync(flight, ct);
}

public sealed class Seats(ISeatStore primary, ISeatStore nearest)
{
    // A seat must never be sold twice, so only the primary region decides.
    // If it can't answer in time, fail and let the user try again (C over A)
    public async Task<bool> BookAsync(
        Guid flight, string seat, CancellationToken ct)
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(TimeSpan.FromSeconds(2)); // the time bound
        return await primary.TryAssignAsync(flight, seat, cts.Token);
    }

    // The seat map may be seconds old: the nearest region answers fast,
    // even during a partition (A and low latency over C)
    public Task<string[]> FreeSeatsAsync(Guid flight, CancellationToken ct) =>
        nearest.GetFreeSeatsAsync(flight, ct);
}
